package system

import (
	"path/filepath"
	"testing"
)

func testModel() *Model {
	return &Model{
		Name: "order-flow",
		Topics: []Topic{
			{TopicKey: TopicKey{Pubsub: "pubsub", Name: "orders"}, Contract: "Order", Field: "Orders"},
		},
		Connectors: []Connector{
			{Name: "erp-destination", Field: "ErpDestination"},
			{Name: "erp-source", Field: "ErpSource"},
			{Name: "order-extractor-source", Field: "OrderExtractorSource"},
			{Name: "order-loader-destination", Field: "OrderLoaderDestination"},
		},
		Components: []Component{
			{AppID: "order-extractor", Kind: "extractor", Topic: &TopicKey{Pubsub: "pubsub", Name: "orders"}, Connector: "order-extractor-source", Connectors: []string{"order-extractor-source"}},
			{AppID: "order-loader", Kind: "loader", Topic: &TopicKey{Pubsub: "pubsub", Name: "orders"}, Connector: "order-loader-destination", Connectors: []string{"order-loader-destination"}},
			{AppID: "audit-loader", Kind: "loader", Topic: &TopicKey{Pubsub: "pubsub", Name: "orders"}},
			{AppID: "erp-sync", Kind: "transactional-integration", Connectors: []string{"erp-source", "erp-destination"}},
		},
		Shared: SharedLibrary{Path: "Contracts", Name: "Contracts"},
	}
}

func TestBuildPayloadShape(t *testing.T) {
	outDir := filepath.Join(t.TempDir(), "order-flow")
	payload, err := buildPayload(testModel(), outDir, "order-flow")
	if err != nil {
		t.Fatal(err)
	}

	if payload["name"] != "order-flow" {
		t.Errorf("name = %v", payload["name"])
	}

	topics, ok := payload["topics"].([]any)
	if !ok || len(topics) != 1 {
		t.Fatalf("topics = %#v", payload["topics"])
	}
	topic := topics[0].(map[string]any)
	wantTopic := map[string]any{"pubsub": "pubsub", "name": "orders", "contract": "Order", "field": "Orders"}
	for k, want := range wantTopic {
		if topic[k] != want {
			t.Errorf("topic[%s] = %v, want %v", k, topic[k], want)
		}
	}

	connectors, ok := payload["connectors"].([]any)
	if !ok || len(connectors) != 4 {
		t.Fatalf("connectors = %#v", payload["connectors"])
	}
	first := connectors[0].(map[string]any)
	if first["name"] != "erp-destination" || first["field"] != "ErpDestination" {
		t.Errorf("connector[0] = %#v", first)
	}

	components, ok := payload["components"].([]any)
	if !ok || len(components) != 4 {
		t.Fatalf("components = %#v", payload["components"])
	}
	extractor := components[0].(map[string]any)
	if extractor["appId"] != "order-extractor" || extractor["kind"] != "extractor" {
		t.Errorf("extractor = %#v", extractor)
	}
	if extractor["topicField"] != "Orders" || extractor["connectorField"] != "OrderExtractorSource" {
		t.Errorf("extractor joins = %#v", extractor)
	}
	loader := components[1].(map[string]any)
	if loader["kind"] != "loader" || loader["connectorField"] != "OrderLoaderDestination" {
		t.Errorf("loader = %#v", loader)
	}
	// A component without a connector carries an empty join, not a missing key.
	audit := components[2].(map[string]any)
	if audit["connectorField"] != "" {
		t.Errorf("connector-less component connectorField = %v, want empty string", audit["connectorField"])
	}
	if audit["topicField"] != "Orders" {
		t.Errorf("connector-less component topicField = %v", audit["topicField"])
	}
	// A transactional component emits from/to joins and no topic join.
	tx := components[3].(map[string]any)
	if tx["kind"] != "transactional-integration" {
		t.Errorf("transactional kind = %v", tx["kind"])
	}
	if tx["fromField"] != "ErpSource" || tx["toField"] != "ErpDestination" {
		t.Errorf("transactional joins = %#v", tx)
	}
	for _, absent := range []string{"topicField", "connectorField"} {
		if _, ok := tx[absent]; ok {
			t.Errorf("transactional component should not carry %s: %#v", absent, tx)
		}
	}

	shared, ok := payload["sharedContracts"].(map[string]any)
	if !ok {
		t.Fatalf("sharedContracts = %#v", payload["sharedContracts"])
	}
	if shared["name"] != "Contracts" {
		t.Errorf("sharedContracts.name = %v", shared["name"])
	}
	absShared, err := filepath.Abs("Contracts")
	if err != nil {
		t.Fatal(err)
	}
	rel, err := filepath.Rel(outDir, absShared)
	if err != nil {
		t.Fatal(err)
	}
	wantInclude := filepath.ToSlash(filepath.Join(rel, "Contracts.csproj"))
	if shared["include"] != wantInclude {
		t.Errorf("sharedContracts.include = %v, want %v", shared["include"], wantInclude)
	}
}

func TestBuildPayloadWithoutConnectors(t *testing.T) {
	m := testModel()
	m.Connectors = nil
	m.Components = m.Components[:1]
	m.Components[0].Connector = ""
	m.Components[0].Connectors = nil

	payload, err := buildPayload(m, filepath.Join(t.TempDir(), "order-flow"), "order-flow")
	if err != nil {
		t.Fatal(err)
	}
	connectors, ok := payload["connectors"].([]any)
	if !ok {
		t.Fatalf("connectors = %#v, want an (empty) list so the template can range over it", payload["connectors"])
	}
	if len(connectors) != 0 {
		t.Errorf("connectors = %#v, want empty", connectors)
	}
}

package system

import (
	"bytes"
	"errors"
	"fmt"
	"strings"
	"testing"
	texttemplate "text/template"

	"github.com/Masterminds/sprig/v3"
	"github.com/huandu/xstrings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

func extractorEntry(path, appID, topic, contract string) template.ScaffoldEntry {
	return blockEntry(path, template.BlockKindExtractor, map[string]any{
		"appId": appID, "topic": topic, "contract": contract, "pubsub": "pubsub",
	})
}

func loaderEntry(path, appID, topic, contract string) template.ScaffoldEntry {
	return blockEntry(path, template.BlockKindLoader, map[string]any{
		"appId": appID, "topic": topic, "contract": contract, "pubsub": "pubsub",
	})
}

func blockEntry(path, kind string, values map[string]any) template.ScaffoldEntry {
	return template.ScaffoldEntry{Path: path, Scaffold: template.Scaffold{
		SchemaVersion: template.ScaffoldSchemaVersion,
		Template:      kind,
		BlockKind:     kind,
		Values:        values,
	}}
}

func sharedEntry(path, name string) template.ScaffoldEntry {
	return template.ScaffoldEntry{Path: path, Scaffold: template.Scaffold{
		SchemaVersion: template.ScaffoldSchemaVersion,
		Template:      "shared-contracts",
		Role:          template.RoleSharedLibrary,
		Values:        map[string]any{"name": name},
	}}
}

func discardWarnf(string, ...any) {}

func TestAssembleHappyPath(t *testing.T) {
	model, err := Assemble([]template.ScaffoldEntry{
		sharedEntry("Contracts", "Contracts"),
		extractorEntry("order-extractor", "order-extractor", "orders", "Order"),
		loaderEntry("order-loader", "order-loader", "orders", "Order"),
	}, discardWarnf)
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}

	if len(model.Components) != 2 {
		t.Fatalf("components = %+v", model.Components)
	}
	if model.Components[0].AppID != "order-extractor" || model.Components[0].Kind != template.BlockKindExtractor {
		t.Errorf("components[0] = %+v", model.Components[0])
	}
	if model.Components[1].AppID != "order-loader" || model.Components[1].Kind != template.BlockKindLoader {
		t.Errorf("components[1] = %+v", model.Components[1])
	}
	if len(model.Topics) != 1 {
		t.Fatalf("shared topic should dedupe, got %+v", model.Topics)
	}
	want := Topic{TopicKey: TopicKey{Pubsub: "pubsub", Name: "orders"}, Contract: "Order", Field: "Orders"}
	if model.Topics[0] != want {
		t.Errorf("topic = %+v, want %+v", model.Topics[0], want)
	}
	if model.Shared != (SharedLibrary{Path: "Contracts", Name: "Contracts"}) {
		t.Errorf("shared = %+v", model.Shared)
	}
}

func TestAssembleDistinctPubsubsMakeDistinctTopics(t *testing.T) {
	extra := blockEntry("audit-loader", template.BlockKindLoader, map[string]any{
		"appId": "audit-loader", "topic": "audits", "contract": "Audit", "pubsub": "audit",
	})
	model, err := Assemble([]template.ScaffoldEntry{
		sharedEntry("Contracts", "Contracts"),
		extractorEntry("order-extractor", "order-extractor", "orders", "Order"),
		extra,
	}, discardWarnf)
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}
	if len(model.Topics) != 2 {
		t.Fatalf("topics = %+v", model.Topics)
	}
	if model.Topics[0].Pubsub != "audit" || model.Topics[1].Pubsub != "pubsub" {
		t.Errorf("topics should sort by (pubsub, name): %+v", model.Topics)
	}
}

func connectedEntry(path, kind, appID, connector string) template.ScaffoldEntry {
	return blockEntry(path, kind, map[string]any{
		"appId": appID, "topic": "orders", "contract": "Order", "pubsub": "pubsub", "connector": connector,
	})
}

func TestAssembleConnectors(t *testing.T) {
	model, err := Assemble([]template.ScaffoldEntry{
		sharedEntry("Contracts", "Contracts"),
		connectedEntry("order-loader", template.BlockKindLoader, "order-loader", "order-loader-destination"),
		connectedEntry("order-extractor", template.BlockKindExtractor, "order-extractor", "order-extractor-source"),
	}, discardWarnf)
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}

	if model.Components[0].Connector != "order-loader-destination" || model.Components[1].Connector != "order-extractor-source" {
		t.Errorf("components = %+v", model.Components)
	}
	want := []Connector{
		{Name: "order-extractor-source", Field: "OrderExtractorSource"},
		{Name: "order-loader-destination", Field: "OrderLoaderDestination"},
	}
	if len(model.Connectors) != 2 || model.Connectors[0] != want[0] || model.Connectors[1] != want[1] {
		t.Errorf("connectors = %+v, want %+v (sorted by name)", model.Connectors, want)
	}
}

func transactionalEntry(path, appID, from, to string) template.ScaffoldEntry {
	return blockEntry(path, template.BlockKindTransactional, map[string]any{
		"appId": appID, "fromConnector": from, "toConnector": to,
	})
}

func TestAssembleTransactional(t *testing.T) {
	model, err := Assemble([]template.ScaffoldEntry{
		sharedEntry("Contracts", "Contracts"),
		extractorEntry("order-extractor", "order-extractor", "orders", "Order"),
		transactionalEntry("erp-sync", "erp-sync", "erp-source", "erp-destination"),
	}, discardWarnf)
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}

	if len(model.Components) != 2 {
		t.Fatalf("components = %+v", model.Components)
	}
	tx := model.Components[1]
	if tx.Kind != template.BlockKindTransactional {
		t.Errorf("kind = %q", tx.Kind)
	}
	if tx.Topic != nil {
		t.Errorf("transactional component should carry no topic: %+v", tx.Topic)
	}
	if tx.Connector != "" {
		t.Errorf("transactional component should not populate the scalar connector: %q", tx.Connector)
	}
	if len(tx.Connectors) != 2 || tx.Connectors[0] != "erp-source" || tx.Connectors[1] != "erp-destination" {
		t.Errorf("connectors = %+v, want [erp-source erp-destination]", tx.Connectors)
	}
	// Both connectors join the system's connector list; the topic count
	// stays at the extractor's one.
	if len(model.Connectors) != 2 || len(model.Topics) != 1 {
		t.Errorf("connectors = %+v, topics = %+v", model.Connectors, model.Topics)
	}
}

func TestAssembleTransactionalErrors(t *testing.T) {
