		Version:       "v1",
		BlockKind:     template.BlockKindLoader,
		Values: map[string]any{
			"appId": "order-loader", "topic": "orders", "contract": "Order", "pubsub": "pubsub",
		},
	})
	if err != nil {
		t.Fatal(err)
