func TestRealSystemHostDependencyWhen(t *testing.T) {
	lib := templatesDir(t)
	tmpl, err := template.LoadTemplate(filepath.Join(lib, "system-host", "template.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	if len(tmpl.Spec.Dependencies) != 1 {
		t.Fatalf("dependencies = %+v", tmpl.Spec.Dependencies)
	}
	dep := tmpl.Spec.Dependencies[0]
	if dep.Template != "shared-contracts" || dep.When == "" {
		t.Fatalf("dependency = %+v", dep)
	}

	// The when expression against resolved payloads, through the same
	// truthiness the engine applies.
	eval := func(payload map[string]any) string {
		values, err := template.Resolve(tmpl, nil, nil, payload, nil)
		if err != nil {
			t.Fatal(err)
		}
		var out strings.Builder
		_ = out
		// renderExpr is unexported; evaluate via a spec.files-style render of
		// a probe file is overkill — Resolve + manual template eval mirrors
		// it. Use the manifest's own expression through text/template.
		tt, err := template.ParseExpr(dep.When)
		if err != nil {
			t.Fatal(err)
		}
		s, err := template.RenderExpr(tt, values)
		if err != nil {
			t.Fatal(err)
		}
		return s
	}

	topicsPayload := map[string]any{
		"name":       "order-flow",
		"topics":     []any{map[string]any{"pubsub": "pubsub", "name": "orders", "contract": "Order"}},
		"connectors": []any{},
		"components": []any{},
	}
	if got := eval(topicsPayload); got == "false" || got == "" {
		t.Errorf("topic system without contracts should render the dependency, when = %q", got)
	}
	withContracts := map[string]any{
		"name":            "order-flow",
		"topics":          []any{map[string]any{"pubsub": "pubsub", "name": "orders", "contract": "Order"}},
		"connectors":      []any{},
		"components":      []any{},
		"sharedContracts": map[string]any{"name": "Contracts", "include": "../Contracts/Contracts.csproj"},
	}
	if got := eval(withContracts); got != "false" {
		t.Errorf("existing contracts should skip the dependency, when = %q", got)
	}
	noTopics := map[string]any{"name": "trans", "topics": []any{}, "connectors": []any{}, "components": []any{}}
	if got := eval(noTopics); got != "false" {
		t.Errorf("topic-free system should skip the dependency, when = %q", got)
	}

	// The dependency's values resolve against the payload: contract comes
	// from the first topic.
	values, err := template.Resolve(tmpl, nil, nil, topicsPayload, nil)
	if err != nil {
		t.Fatal(err)
	}
	contract, err := template.RenderExpr(mustExpr(t, dep.Values["contract"]), values)
	if err != nil {
		t.Fatal(err)
	}
	if contract != "Order" {
		t.Errorf("dependency contract = %q, want Order", contract)
	}

	// And the dependency template itself loads from the same checkout.
	if _, err := template.LoadTemplate(filepath.Join(lib, dep.Template, "template.yaml")); err != nil {
		t.Fatalf("dependency template: %v", err)
	}
}

func mustExpr(t *testing.T, expr string) any {
	t.Helper()
	tt, err := template.ParseExpr(expr)
	if err != nil {
		t.Fatal(err)
	}
	return tt
}
